// rpm as unspent — and a model row whose rpm_limit is NULL escapes pre-throttling
// entirely — so it keeps dispatching and eats real 429s.
const DEFAULT_PROVIDER_MINUTE_REQUEST_CAPS: Record<string, number> = {
  nvidia: 40,
