export function canUseProviderTokens(platform: string, keyId: number, estimatedTokens: number, now = Date.now()): boolean {
  const cap = getProviderDailyTokenCap(platform);
  if (cap === null) return true;
  const inFlight = provisionalProviderTokens(platform, keyId, now);
  const used = withDb(db => {
    const row = db.prepare(`
      SELECT COALESCE(SUM(tokens), 0) AS used
        FROM rate_limit_usage
       WHERE platform = ?
         AND key_id = ?
         AND kind = 'tokens'
         AND created_at_ms > ?
    `).get(platform, keyId, now - msSinceUtcMidnight(now)) as { used: number };
    return row.used;
  }) ?? 0;
  return used + inFlight + estimatedTokens < cap;
}

export function recordRequestUsage(platform: string, modelId: string, keyId: number, tokens = 0, now = Date.now()): void {
  recordUsage(platform, modelId, keyId, 'request', 1, now);
  if (tokens > 0) {
    recordUsage(platform, modelId, keyId, 'tokens', tokens, now);
  }
}

