export function isOnCooldown(platform: string, modelId: string, keyId: number, now = Date.now()): boolean {
  return withDb(db => {
    const row = db.prepare(`
      SELECT expires_at_ms FROM rate_limit_cooldowns
       WHERE platform = ? AND model_id = ? AND key_id = ? AND expires_at_ms > ?
    `).get(platform, modelId, keyId, now);
    return row !== undefined;
  }) ?? false;
