export function setCooldown(platform: string, modelId: string, keyId: number, durationMs: number, now = Date.now()): void {
  const expiresAt = now + durationMs;
  withDb(db => {
    db.prepare(`
      INSERT INTO rate_limit_cooldowns (platform, model_id, key_id, expires_at_ms)
      VALUES (?, ?, ?, ?)
      ON CONFLICT(platform, model_id, key_id)
      DO UPDATE SET expires_at_ms = MAX(expires_at_ms, excluded.expires_at_ms)
    `).run(platform, modelId, keyId, expiresAt);
  });
}

export function getSoonestCooldownExpiry(): number | null {
  return withDb(db => {
    const row = db.prepare(`
      SELECT MIN(expires_at_ms) as soonest FROM rate_limit_cooldowns WHERE expires_at_ms > ?
    `).get(Date.now()) as { soonest: number | null };
    return row?.soonest ?? null;
  }) ?? null;
}
