  const n = Number(raw);
  return Number.isFinite(n) && n >= 0 && n <= 1 ? n : TASK_WEIGHT_SHARE;
}

// null clears back to the default; a value outside 0..1 throws.
export function setTaskWeightShare(value: number | null): void {
